-- Backend Engineering ("The Fracture") -- "Kafka & Event Streaming" content.
-- Opens Arc IV (Stream). 1 campaign, 2 operations, 12 missions (11 lessons + boss),
-- following the same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every prior Act. Uses the slug-based id scheme
-- (world-be-kafka / mission-be-kafka-NN) introduced for this wave of Acts.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be-kafka', 'world-be-kafka', 'kafka-and-event-streaming', 'Kafka & Event Streaming', 'RabbitMQ solved the fanout crisis. The auditors reviewing that response want something RabbitMQ was never built for: a full, replayable, append-only record of every event Forge has ever emitted, for as long as compliance requires it.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be-kafka-1', 'campaign-be-kafka', 'the-log-model', 'The Log Model', 'Why an event log is not a queue, Kafka''s architecture, and the four properties -- brokers, topics, partitions and offsets -- that describe everything Kafka actually stores.', 1),
  ('operation-be-kafka-2', 'campaign-be-kafka', 'consumers-and-guarantees', 'Consumers and Guarantees', 'How consumers actually read the log, what a partition key buys you, how long a replay window really lasts, and the commit and rebalance mechanics behind every duplicate or lost event this Act traces.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be-kafka-01', 'world-be-kafka', 'campaign-be-kafka', 'operation-be-kafka-1', 'queue-vs-event-log', 'Queue vs Event Log', 'RabbitMQ consumed and forgot, on purpose. The auditors want the opposite: everything kept, in order, replayable months later. That one difference is the entire reason Kafka exists.', 'advanced', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"queue-vs-event-log-sim"}'::jsonb, '{"xp":225,"credits":43}'::jsonb, false, 1),
  ('mission-be-kafka-02', 'world-be-kafka', 'campaign-be-kafka', 'operation-be-kafka-1', 'kafka-architecture', 'Kafka Architecture', 'Producer, broker, topic, partition, offset, consumer -- the pieces that describe the entire path an event takes through Kafka, and every bug this Act traces back to exactly one of them.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-kafka-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"kafka-architecture-sim"}'::jsonb, '{"xp":227,"credits":43}'::jsonb, false, 2),
  ('mission-be-kafka-03', 'world-be-kafka', 'campaign-be-kafka', 'operation-be-kafka-1', 'brokers-and-topics', 'Brokers and Topics', 'A topic is a name. A broker is a machine. What actually determines whether a topic survives losing one of them is a setting almost nobody sets on purpose.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-kafka-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"brokers-and-topics-sim"}'::jsonb, '{"xp":229,"credits":43}'::jsonb, false, 3),
  ('mission-be-kafka-04', 'world-be-kafka', 'campaign-be-kafka', 'operation-be-kafka-1', 'partitions', 'Partitions', 'A partition is the real unit Kafka parallelizes and orders -- and the one number in this whole system you can raise freely but should never, ever lower.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-kafka-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"partitions-sim"}'::jsonb, '{"xp":231,"credits":44}'::jsonb, false, 4),
  ('mission-be-kafka-05', 'world-be-kafka', 'campaign-be-kafka', 'operation-be-kafka-1', 'offsets', 'Offsets', 'An offset looks like a universal sequence number. It isn''t. It''s a local bookmark, and mistaking the two has already confused one caseworker into filing a report about a duplicate that was never actually a duplicate.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-kafka-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"offsets-sim"}'::jsonb, '{"xp":232,"credits":44}'::jsonb, false, 5),
  ('mission-be-kafka-06', 'world-be-kafka', 'campaign-be-kafka', 'operation-be-kafka-1', 'producers', 'Producers', 'A producer decides, with one setting, whether "sent" means "written to disk on the leader" or "handed to the network and hoped for the best." An audit trail cannot afford to guess which one it got.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-kafka-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"producers-sim"}'::jsonb, '{"xp":234,"credits":44}'::jsonb, false, 6),
  ('mission-be-kafka-07', 'world-be-kafka', 'campaign-be-kafka', 'operation-be-kafka-2', 'consumer-groups', 'Consumer Groups', 'A consumer group is how Kafka spreads work across instances without any of them talking to each other -- and how a perfectly healthy consumer can end up sitting there doing nothing at all.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-kafka-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"consumer-groups-sim"}'::jsonb, '{"xp":235,"credits":45}'::jsonb, false, 7);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be-kafka-08', 'world-be-kafka', 'campaign-be-kafka', 'operation-be-kafka-2', 'partition-keys-and-ordering', 'Partition Keys and Ordering', 'Kafka only promises order within a single partition, never across a whole topic. The partition key is the one thing standing between "this citizen''s updates arrive in order" and "they don''t."', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-kafka-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"partition-keys-ordering-sim"}'::jsonb, '{"xp":236,"credits":45}'::jsonb, false, 8),
  ('mission-be-kafka-09', 'world-be-kafka', 'campaign-be-kafka', 'operation-be-kafka-2', 'retention-and-replay', 'Retention and Replay', 'A replayable log is only replayable for as long as retention says it is. Past that window, the data isn''t hard to find -- it''s already gone.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-kafka-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"retention-and-replay-sim"}'::jsonb, '{"xp":237,"credits":45}'::jsonb, false, 9),
  ('mission-be-kafka-10', 'world-be-kafka', 'campaign-be-kafka', 'operation-be-kafka-2', 'commits-and-rebalances', 'Commits and Rebalances', 'Committing an offset is a promise: everything up to here is done. Make that promise too early, or let a rebalance catch it mid-flight, and the promise turns out to have been a lie.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-kafka-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"commits-and-rebalances-sim"}'::jsonb, '{"xp":238,"credits":46}'::jsonb, false, 10),
  ('mission-be-kafka-11', 'world-be-kafka', 'campaign-be-kafka', 'operation-be-kafka-2', 'delivery-semantics', 'Delivery Semantics', 'At-most-once, at-least-once, effectively-once -- three different bets about what happens when a consumer crashes at the worst possible moment, and only one of them is actually safe for a citizen dispatch record.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-kafka-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"delivery-semantics-sim"}'::jsonb, '{"xp":240,"credits":46}'::jsonb, false, 11),
  ('mission-be-kafka-12', 'world-be-kafka', 'campaign-be-kafka', 'operation-be-kafka-2', 'the-rebalance-storm', 'The Rebalance Storm', 'A deploy at peak load, an eleven-second rebalance, and one partition''s committed offset that turns out to have been a few events behind the whole time. Everything this Act taught, at once.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-kafka-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"rebalance-storm-boss-sim"}'::jsonb, '{"xp":533,"credits":123,"badgeIds":["rebalance-storm"],"skillXp":{"messaging":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be-kafka-01', 1, 'mira', 'RabbitMQ earned its keep -- the fanout crisis is over. Now the auditors reviewing that incident want something RabbitMQ was never designed to give them: a full, replayable record of every event Forge has ever emitted, for as long as compliance says we have to keep it.'),
  ('mission-be-kafka-01', 2, 'forge', 'That''s not a queue problem. A queue is built to forget -- consume a message and it''s gone, on purpose, so nothing processes it twice. An audit trail needs the opposite: everything kept, in order, replayable from any point in the past.'),
  ('mission-be-kafka-01', 3, 'mira', 'That distinction -- queue versus log -- is the whole reason we''re standing up Kafka instead of just scaling RabbitMQ further. Get it wrong in your head and every concept after it will feel like a bolted-on RabbitMQ feature. It isn''t. It''s a different model entirely.'),

  ('mission-be-kafka-02', 1, 'forge', 'Kafka''s architecture, in five pieces: a producer writes events to a topic. The topic is split into partitions, spread across brokers. A consumer reads from a partition, tracking its own position with an offset. Nothing here forgets anything on its own -- deletion is a retention policy, not a side effect of reading.'),
  ('mission-be-kafka-02', 2, 'mira', 'Same discipline as RabbitMQ: learn the five pieces exactly. Every bug this Act traces back to one of them doing something you didn''t expect.'),

  ('mission-be-kafka-03', 1, 'mira', 'A topic is a name -- a logical stream. A broker is an actual server, one of several forming the Kafka cluster, and it''s the thing that really holds the data on disk.'),
  ('mission-be-kafka-03', 2, 'forge', 'How well a topic survives losing a broker isn''t about the topic at all. It''s a setting called replication factor, and the default nobody changes is the one that guarantees it won''t survive at all.'),

  ('mission-be-kafka-04', 1, 'forge', 'A partition is the actual unit Kafka parallelizes work across, and the actual unit it guarantees order within. A topic with six partitions is really six independent, ordered logs wearing one name.'),
  ('mission-be-kafka-04', 2, 'mira', 'You can add partitions to a topic later without much drama. You should never remove them -- and by the end of this mission you''ll know exactly why.'),

  ('mission-be-kafka-05', 1, 'mira', 'Every partition keeps one thing no other part of Kafka has: an offset, a plain integer that only ever goes up, marking each event''s position in that one partition''s log.'),
  ('mission-be-kafka-05', 2, 'forge', 'Key word: that one partition''s log. Offset 500 in partition 2 and offset 500 in partition 5 have nothing to do with each other. They''re not even close to the same event.'),

  ('mission-be-kafka-06', 1, 'forge', 'A producer decides how durable "sent" actually is with one setting: acks. Zero means fire and forget -- don''t even wait to hear back. One means the partition leader wrote it. All means every in-sync replica wrote it before the producer hears success.'),
  ('mission-be-kafka-06', 2, 'mira', 'An audit trail cannot afford to guess which of those three it actually got. Neither can a citizen dispatch record.'),

  ('mission-be-kafka-07', 1, 'mira', 'A consumer group is Kafka''s answer to "how do I scale this without every instance processing every event." Inside one group, each partition is owned by exactly one consumer at a time -- the group as a whole processes the topic exactly once.'),
  ('mission-be-kafka-07', 2, 'forge', 'A second, independent consumer group reading the same topic gets its own full copy, completely unaware the first group exists. Groups are the unit of "who gets what," not consumers.'),

  ('mission-be-kafka-08', 1, 'forge', 'A partition key is just a value a producer attaches to an event -- most often an entity id. Kafka hashes it, and that hash decides which partition the event lands in, deterministically, every time.'),
  ('mission-be-kafka-08', 2, 'mira', 'That determinism is the whole point: every event for the same key always lands in the same partition, and Kafka only guarantees order within a partition. Same key, same partition, same order. No key, and you''ve given that up.'),

  ('mission-be-kafka-09', 1, 'mira', 'Retention decides how long a log actually holds an event before Kafka reclaims the disk -- by age, by size, whichever limit hits first. Past that window, replay isn''t slow. It''s impossible; the data is already gone.'),
  ('mission-be-kafka-09', 2, 'forge', 'The default is seven days. Nobody in this building thought to ask whether that was long enough for an audit trail until the auditors asked for day forty-five.'),

  ('mission-be-kafka-10', 1, 'forge', 'Committing an offset is a promise to Kafka: everything up through here is done, don''t hand it to me again. Auto-commit makes that promise on a timer, whether processing actually finished or not.'),
  ('mission-be-kafka-10', 2, 'mira', 'And a rebalance -- any time group membership changes, a consumer joins, leaves, or is declared dead -- briefly takes every partition away from everybody before handing them back out. Whatever was committed at that exact moment is what the next owner trusts completely.'),

  ('mission-be-kafka-11', 1, 'forge', 'Three bets, and you only get to pick one per pipeline. Commit before processing: nothing''s ever double-applied, but a crash mid-processing loses the event outright. Commit after: nothing''s ever lost, but a crash between finishing and committing reprocesses it.'),
  ('mission-be-kafka-11', 2, 'mira', 'The third bet -- effectively-once -- isn''t a delivery guarantee at all. It''s at-least-once delivery plus processing that''s safe to repeat. Kafka can''t give you that for free. You have to build it.'),

  ('mission-be-kafka-12', 1, 'forge', 'Incident: during peak load, a routine deploy triggered a consumer-group rebalance on advisory-audit-group. For about eleven seconds, every partition in that group was owned by nobody at all.'),
  ('mission-be-kafka-12', 2, 'mira', 'And when ownership settled back out, we started seeing duplicate processing. Same citizen events, applied twice, on at least one partition.'),
  ('mission-be-kafka-12', 3, 'forge', 'Traced it to partition 4. Its last committed offset was a few events behind where the old consumer had actually gotten to, processing-wise, the moment the rebalance hit and took the partition away from it.'),
  ('mission-be-kafka-12', 4, 'mira', 'So whoever picked up partition 4 afterward started from that stale committed offset -- and reprocessed everything the old owner had already handled but never got the chance to commit.'),
  ('mission-be-kafka-12', 5, 'forge', 'While I was tracing exactly which events got hit twice, I found something else. One of the reprocessed message keys is a citizen record id with a doubled slash appended to it -- and that partition has reprocessed more than any other partition we''ve ever measured, going back further than this one incident.'),
  ('mission-be-kafka-12', 6, 'mira', 'Noted. File it -- same as always. It isn''t what''s in front of us today, and I don''t think it''s a coincidence either.'),
  ('mission-be-kafka-12', 7, 'forge', 'Either way, the rebalance itself isn''t the bug. It''s doing exactly what it''s supposed to do when group membership changes. The bug is trusting a committed offset that was already stale the moment the deploy started.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be-kafka-01-o1', 'mission-be-kafka-01', 1, 'Diagnose why a log is the actual fix', 'Find the evidence that explains why even a perfectly healthy queue can never satisfy the audit requirement.'),
  ('mission-be-kafka-02-o1', 'mission-be-kafka-02', 1, 'Match the architecture piece to its job', 'Match each Kafka architecture piece to what it actually does.'),
  ('mission-be-kafka-03-o1', 'mission-be-kafka-03', 1, 'Diagnose the unavailable partitions', 'Find the evidence that explains why losing one broker made a third of a topic''s partitions completely unavailable.'),
  ('mission-be-kafka-04-o1', 'mission-be-kafka-04', 1, 'Explain the one-way partition count', 'Choose the reason a topic''s partition count can be raised later but should never be lowered.'),
  ('mission-be-kafka-05-o1', 'mission-be-kafka-05', 1, 'Diagnose the offset confusion', 'Find the evidence that explains why the same offset number can point to two completely unrelated events.'),
  ('mission-be-kafka-06-o1', 'mission-be-kafka-06', 1, 'Find the durability bug', 'Debug a producer configuration that loses audit events with zero errors logged.'),
  ('mission-be-kafka-07-o1', 'mission-be-kafka-07', 1, 'Diagnose the idle consumer', 'Find the evidence that explains why a healthy, connected consumer never receives a single message.'),
  ('mission-be-kafka-08-o1', 'mission-be-kafka-08', 1, 'Explain what determines a partition', 'Choose what actually decides which partition a keyed or unkeyed event lands in.'),
  ('mission-be-kafka-08-o2', 'mission-be-kafka-08', 2, 'Find the ordering bug', 'Debug a producer call that silently gives up per-citizen ordering.'),
  ('mission-be-kafka-09-o1', 'mission-be-kafka-09', 1, 'Diagnose the impossible replay', 'Find the evidence that explains why 45-day-old events can never be replayed, no matter what the consumer does.'),
  ('mission-be-kafka-10-o1', 'mission-be-kafka-10', 1, 'Find the premature commit', 'Debug a consumer that commits an offset before it has actually finished processing it.'),
  ('mission-be-kafka-10-o2', 'mission-be-kafka-10', 2, 'Order the rebalance', 'Order the sequence of events that happens during a consumer-group rebalance.'),
  ('mission-be-kafka-11-o1', 'mission-be-kafka-11', 1, 'Match the commit strategy to its guarantee', 'Match each commit-timing strategy to the delivery semantic it actually produces.'),
  ('mission-be-kafka-12-o1', 'mission-be-kafka-12', 1, 'Diagnose the redelivery', 'Find the evidence that explains why this rebalance produced duplicate processing, rather than just a brief pause.'),
  ('mission-be-kafka-12-o2', 'mission-be-kafka-12', 2, 'Design the fix', 'Choose the combination of changes that actually closes the gap between processing and committing.'),
  ('mission-be-kafka-12-o3', 'mission-be-kafka-12', 3, 'Confirm the escalation', 'Find the piece of evidence from the key audit that is the actual new finding, not just confirmation the rebalance worked as designed.'),
  ('mission-be-kafka-12-o4', 'mission-be-kafka-12', 4, 'Close the incident', 'Synthesize the diagnosis, the fix, and the audit finding into the full resolution.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be-kafka-01-o1-c1', 'mission-be-kafka-01-o1', 1, 'investigation', 'Which evidence explains why even a perfectly healthy queue can never satisfy this requirement?', '{"evidence":[{"id":"ev1","label":"Consume-and-remove behavior","detail":"Each advisory message is acked and removed from the queue the instant a consumer finishes processing it -- nothing about the message persists afterward, success or failure."},{"id":"ev2","label":"Auditor requirement","detail":"Auditors need to replay the exact sequence of every event emitted in the last 180 days, including ones every current consumer already fully processed."},{"id":"ev3","label":"Current queue depth","detail":"advisory.audit sits at zero messages during normal operation -- by design, a healthy queue is an empty queue."}],"question":"Which evidence explains why even a perfectly healthy queue can never satisfy this requirement?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be-kafka-02-o1-c1', 'mission-be-kafka-02-o1', 1, 'drag_and_drop', 'Match each Kafka architecture piece to what it actually does.', '{"items":[{"id":"p1","text":"Producer"},{"id":"p2","text":"Broker"},{"id":"p3","text":"Topic"},{"id":"p4","text":"Partition"},{"id":"p5","text":"Offset"},{"id":"p6","text":"Consumer"}],"targets":[{"id":"t1","label":"Writes events into a topic, with no idea who -- if anyone -- reads them"},{"id":"t2","label":"A server that stores some partitions and serves reads and writes for them"},{"id":"t3","label":"A named, logical stream of events that is actually split across one or more ordered partitions"},{"id":"t4","label":"One ordered, append-only sub-log of a topic -- the actual unit Kafka stores and parallelizes"},{"id":"t5","label":"A consumer''s bookmark: the position it has read up to within a single partition"},{"id":"t6","label":"Reads events starting from some offset and does the actual work"}]}'::jsonb, '{"correctMapping":{"p1":"t1","p2":"t2","p3":"t3","p4":"t4","p5":"t5","p6":"t6"}}'::jsonb),

  ('mission-be-kafka-03-o1-c1', 'mission-be-kafka-03-o1', 1, 'investigation', 'Which evidence explains why losing one broker made a third of the topic''s partitions completely unavailable, not just slower?', '{"evidence":[{"id":"ev1","label":"Topic config","detail":"advisory.audit topic was created with partitions=6, replication-factor=1."},{"id":"ev2","label":"Incident timeline","detail":"Broker 3 was taken down for routine maintenance; three of the topic''s six partitions, all hosted only on broker 3, became unreadable and unwritable for the full 40 minutes it was offline."},{"id":"ev3","label":"Cluster size","detail":"The Kafka cluster has 4 brokers total, so 3 other brokers had spare capacity the entire time."}],"question":"Which evidence explains why losing one broker made a third of the topic''s partitions completely unavailable, not just slower?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be-kafka-04-o1-c1', 'mission-be-kafka-04-o1', 1, 'multiple_choice', 'A topic''s partition count can be increased later, but operators are warned never to decrease it. Why?', '{"question":"A topic''s partition count can be increased later, but operators are warned never to decrease it. Why?","options":[{"id":"a","text":"Decreasing partitions frees broker disk space instantly, which risks data loss"},{"id":"b","text":"Partition assignment is typically hash(key) mod partitionCount -- changing that number changes which partition future events with the same key land in, silently breaking per-key ordering for every key already in flight"},{"id":"c","text":"Kafka enforces partition counts as powers of two, so a decreased number usually isn''t valid anyway"},{"id":"d","text":"It doesn''t matter -- partition count has no effect on routing"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-kafka-05-o1-c1', 'mission-be-kafka-05-o1', 1, 'investigation', 'Which evidence explains why the same offset number can point to two completely unrelated events?', '{"evidence":[{"id":"ev1","label":"Confused report","detail":"A caseworker insists two completely different citizen events must be identical because both show offset 500 in the dashboard."},{"id":"ev2","label":"Specific instance","detail":"One event is at offset 500 in partition 2. The other is at offset 500 in partition 5 -- two entirely separate logs."},{"id":"ev3","label":"Partition mechanics","detail":"The topic has 6 partitions total, each maintaining its own independent, monotonically increasing offset counter starting at 0."}],"question":"Which evidence explains why the same offset number can point to two completely unrelated events?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),

  ('mission-be-kafka-06-o1-c1', 'mission-be-kafka-06-o1', 1, 'code_debugging', 'Audit events are vanishing with zero errors logged whenever a partition leader crashes right after a send. Which line is responsible?', '{"language":"javascript","code":"const producer = kafka.producer();\nawait producer.send({\n  topic: \"advisory.audit\",\n  acks: 0,\n  messages: [{ key: citizenId, value: JSON.stringify(event) }],\n});","question":"Audit events are vanishing with zero errors logged whenever a partition leader crashes right after a send. Which line is responsible?"}'::jsonb, '{"requiredLineIds":["  acks: 0,"]}'::jsonb),

  ('mission-be-kafka-07-o1-c1', 'mission-be-kafka-07-o1', 1, 'investigation', 'Which evidence explains why one healthy, connected consumer never receives any messages?', '{"evidence":[{"id":"ev1","label":"Consumer group status","detail":"advisory-audit-group has 5 active consumer instances, all connected and reporting healthy."},{"id":"ev2","label":"Topic detail","detail":"advisory.audit has 4 partitions."},{"id":"ev3","label":"Metrics","detail":"One of the 5 consumer instances has processed zero messages since it started, while the other four are evenly loaded."}],"question":"Which evidence explains why one healthy, connected consumer never receives any messages?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be-kafka-08-o1-c1', 'mission-be-kafka-08-o1', 1, 'multiple_choice', 'A producer publishes two events for the same citizenId, once with a partition key set to that citizenId and once with no key at all. What actually determines which partition each one lands in?', '{"question":"A producer publishes two events for the same citizenId, once with a partition key set to that citizenId and once with no key at all. What actually determines which partition each one lands in?","options":[{"id":"a","text":"Kafka round-robins every message across partitions regardless of key, so both are equally random"},{"id":"b","text":"With a key set, Kafka deterministically hashes it to the same partition every time, keeping that citizen''s events in order; with no key, Kafka distributes messages without any such guarantee, most commonly by rotating across partitions"},{"id":"c","text":"The key only affects the message''s value payload, never its routing"},{"id":"d","text":"Partition assignment is decided by the consumer, never the producer"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-kafka-08-o2-c1', 'mission-be-kafka-08-o2', 1, 'code_debugging', 'Two updates for the same citizen are sometimes applied out of order downstream, even though the producer sent them in the correct sequence. Which line is missing the one property that would have kept them in order?', '{"language":"javascript","code":"await producer.send({\n  topic: \"citizen.updates\",\n  messages: [\n    { value: JSON.stringify(event) },\n  ],\n});","question":"Two updates for the same citizen are sometimes applied out of order downstream, even though the producer sent them in the correct sequence. Which line is missing the one property that would have kept them in order?"}'::jsonb, '{"requiredLineIds":["    { value: JSON.stringify(event) },"]}'::jsonb),

  ('mission-be-kafka-09-o1-c1', 'mission-be-kafka-09-o1', 1, 'investigation', 'Which evidence explains why the 45-day-old events can never be replayed, no matter what the consumer does?', '{"evidence":[{"id":"ev1","label":"Topic config","detail":"advisory.audit topic has retention.ms set to 604800000 (7 days) -- the Kafka default."},{"id":"ev2","label":"Auditor request","detail":"Auditors asked to replay every advisory event from 45 days ago."},{"id":"ev3","label":"Replay attempt","detail":"Seeking any consumer to an offset older than 7 days returns an out-of-range offset error -- that segment of the log has already been physically deleted from disk."}],"question":"Which evidence explains why the 45-day-old events can never be replayed, no matter what the consumer does?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be-kafka-10-o1-c1', 'mission-be-kafka-10-o1', 1, 'code_debugging', 'If processAdvisory throws on a malformed event, Kafka has already been told this offset is fully processed. Which line causes that?', '{"language":"javascript","code":"consumer.on(\"message\", async (message) => {\n  consumer.commitOffsets([{ topic, partition, offset: message.offset + 1 }]);\n  await processAdvisory(JSON.parse(message.value.toString()));\n});","question":"If processAdvisory throws on a malformed event, Kafka has already been told this offset is fully processed. Which line causes that?"}'::jsonb, '{"requiredLineIds":["  consumer.commitOffsets([{ topic, partition, offset: message.offset + 1 }]);"]}'::jsonb),
  ('mission-be-kafka-10-o2-c1', 'mission-be-kafka-10-o2', 1, 'interactive_diagram', 'Order the sequence of events that happens during a consumer-group rebalance.', '{"diagramId":"rebalance-sequence","hotspots":[{"id":"member_change","label":"Group membership changes","explanation":"A consumer joins, leaves, or is declared dead by the group coordinator (missed heartbeats, for example)."},{"id":"revoke","label":"The coordinator revokes every partition assignment in the group","explanation":"For a brief window, no consumer in the group owns any partition at all."},{"id":"reassign","label":"The coordinator computes a new partition-to-consumer assignment","explanation":"Every partition gets handed to exactly one consumer in the group again."},{"id":"resume","label":"Each consumer resumes reading its newly assigned partitions","explanation":"Starting from whatever offset was last actually committed -- not from wherever the previous owner happened to stop."}],"task":"Order the sequence of events that happens during a consumer-group rebalance."}'::jsonb, '{"correctOrderIds":["member_change","revoke","reassign","resume"]}'::jsonb),

  ('mission-be-kafka-11-o1-c1', 'mission-be-kafka-11-o1', 1, 'drag_and_drop', 'Match each commit-timing strategy to the delivery semantic it actually produces.', '{"items":[{"id":"i1","text":"Offset committed immediately after receipt, before processing starts"},{"id":"i2","text":"Offset committed only after processing completes successfully"},{"id":"i3","text":"Idempotent producer plus a consumer that applies changes through a dedup-aware, repeat-safe write"}],"targets":[{"id":"t1","label":"At-most-once: safe against duplicates, but a crash mid-processing loses the event forever"},{"id":"t2","label":"At-least-once: safe against loss, but a crash after processing and before commit reprocesses the event"},{"id":"t3","label":"Effectively-once: neither lost nor double-applied, achieved by making the processing itself safe to repeat -- not by any single delivery guarantee alone"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3"}}'::jsonb),

  ('mission-be-kafka-12-o1-c1', 'mission-be-kafka-12-o1', 1, 'investigation', 'Which evidence explains why this specific rebalance produced duplicate processing, rather than just a brief pause?', '{"evidence":[{"id":"ev1","label":"Rebalance log","detail":"The rebalance completed in 11 seconds and reassigned all 6 partitions to the 6 members of advisory-audit-group -- standard behavior for a group-membership change."},{"id":"ev2","label":"Offset trace","detail":"Partition 4''s last committed offset was 118402. The old consumer had actually finished processing up through offset 118417 -- 15 events processed but never committed -- when the rebalance revoked its assignment."},{"id":"ev3","label":"Deploy log","detail":"The deploy that triggered the rebalance rolled out a new consumer image with no logic changes to the offset-commit path."}],"question":"Which evidence explains why this specific rebalance produced duplicate processing, rather than just a brief pause?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-be-kafka-12-o2-c1', 'mission-be-kafka-12-o2', 1, 'multiple_choice', 'Which combination of changes actually closes the gap between processing and committing, without making the system fragile in some other way?', '{"question":"Which combination of changes actually closes the gap between processing and committing, without making the system fragile in some other way?","options":[{"id":"a","text":"Disable rebalancing entirely so partition ownership never changes"},{"id":"b","text":"Increase the auto-commit interval so commits happen less often"},{"id":"c","text":"Commit an offset only after processing for that offset has actually completed, and make the processing itself idempotent so any events reprocessed after a future rebalance don''t corrupt state"},{"id":"d","text":"Reduce the topic to 1 partition so there is nothing left to rebalance"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-be-kafka-12-o3-c1', 'mission-be-kafka-12-o3', 1, 'investigation', 'Which piece of evidence from the key audit is the actual new finding, not just confirmation that the rebalance mechanics worked as designed?', '{"evidence":[{"id":"ev1","label":"Rebalance timeline","detail":"All 6 partitions were successfully reassigned and resumed processing within 11 seconds -- consistent with a normal, if inconveniently timed, rebalance."},{"id":"ev2","label":"Message key audit","detail":"One of the duplicated events in partition 4 carries a message key that is a citizen record id with a doubled slash appended to it, and partition 4 has reprocessed messages more often than every other partition in this topic combined, across every incident on record, not just this one."},{"id":"ev3","label":"Team note","detail":"The consumer code path that reprocesses partition 4 has never once thrown a validation error on that malformed key -- it is accepted and processed like any other."}],"question":"Which piece of evidence from the key audit is the actual new finding, not just confirmation that the rebalance mechanics worked as designed?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-be-kafka-12-o4-c1', 'mission-be-kafka-12-o4', 1, 'boss_encounter', 'Having diagnosed the redelivery, designed the fix, and confirmed what the key audit turned up, state the full resolution.', '{"stages":[{"objectiveRef":"mission-be-kafka-12-o1","label":"Diagnose the redelivery"},{"objectiveRef":"mission-be-kafka-12-o2","label":"Design the fix"},{"objectiveRef":"mission-be-kafka-12-o3","label":"Confirm the escalation"}],"task":"Having diagnosed the redelivery, designed the fix, and confirmed what the key audit turned up, state the full resolution: the rebalance itself was not the bug -- a committed offset that lagged behind actual processing was, and committing only after processing completes, backed by idempotent handling, closes that gap. Separately, partition 4''s disproportionate reprocessing and its doubled-slash citizen key are filed, unresolved, as the same pattern surfacing again in the event-streaming layer."}'::jsonb, '{"requiredObjectiveIds":["mission-be-kafka-12-o1","mission-be-kafka-12-o2","mission-be-kafka-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be-kafka-01-o1-c1', 'orientation', 'The auditor requirement describes what''s needed. Two of these three entries describe the current system''s behavior -- only one of those explains the mismatch at its root.', 10, 1),
  ('mission-be-kafka-01-o1-c1', 'concept', 'A message queue''s whole job is to make ''processed'' mean ''gone.'' That design choice is exactly what a replay requirement runs into.', 20, 2),
  ('mission-be-kafka-01-o1-c1', 'solution', 'ev1: consuming a message removes it, permanently, the instant it''s processed -- there is nothing left to replay no matter how the queue is configured.', 30, 3),

  ('mission-be-kafka-02-o1-c1', 'orientation', 'One of these pieces only decides. One only stores on disk. Two are the ends of the pipeline, and two are what connects position to place.', 10, 1),
  ('mission-be-kafka-02-o1-c1', 'concept', 'A topic is a name; a partition is where the bytes actually live. An offset only makes sense relative to one specific partition.', 20, 2),
  ('mission-be-kafka-02-o1-c1', 'solution', 'Producer writes, broker hosts, topic names the stream, partition is the real ordered sub-log, offset marks position within it, consumer reads and works.', 30, 3),

  ('mission-be-kafka-03-o1-c1', 'orientation', 'Two of these confirm the cluster had spare capacity and the outage really happened. One explains why that spare capacity didn''t matter.', 10, 1),
  ('mission-be-kafka-03-o1-c1', 'concept', 'Replication factor 1 means exactly one copy of each partition exists anywhere in the cluster -- lose the broker holding it and there is no second copy to fail over to.', 20, 2),
  ('mission-be-kafka-03-o1-c1', 'solution', 'ev1: replication-factor=1 means every partition has exactly one copy; the three other brokers having spare capacity is irrelevant if none of them hold a replica.', 30, 3),

  ('mission-be-kafka-04-o1-c1', 'orientation', 'Think about what actually decides which partition a keyed event lands in, and what happens to that decision if the denominator changes.', 10, 1),
  ('mission-be-kafka-04-o1-c1', 'solution', 'b: partition routing is typically hash(key) mod partitionCount -- lowering the count changes that mapping and breaks per-key ordering for every key already in flight.', 20, 2),

  ('mission-be-kafka-05-o1-c1', 'orientation', 'The complaint and the specific instance both describe the confusion. One entry explains the actual mechanism behind it.', 10, 1),
  ('mission-be-kafka-05-o1-c1', 'concept', 'Every partition keeps its own counter starting from 0 -- there is no shared, topic-wide sequence number anywhere in Kafka.', 20, 2),
  ('mission-be-kafka-05-o1-c1', 'solution', 'ev3: each partition has its own independent offset counter, so ''offset 500'' means nothing on its own without also knowing which partition.', 30, 3),

  ('mission-be-kafka-06-o1-c1', 'orientation', 'The setting on this line trades durability for speed, all the way down to zero guarantee.', 10, 1),
  ('mission-be-kafka-06-o1-c1', 'concept', 'acks: 0 means the producer never waits to hear whether the broker even received the message, let alone wrote it -- a crash right after send loses it with nothing to show for it.', 20, 2),
  ('mission-be-kafka-06-o1-c1', 'solution', 'acks: 0 is the bug -- an audit trail needs at least acks: 1 (leader wrote it) or acks: all (every in-sync replica did) before treating a send as durable.', 30, 3),

  ('mission-be-kafka-07-o1-c1', 'orientation', 'The consumer isn''t unhealthy. Count what it''s actually competing for.', 10, 1),
  ('mission-be-kafka-07-o1-c1', 'concept', 'Inside one consumer group, a partition can be owned by exactly one consumer at a time -- there is no such thing as two consumers sharing a partition.', 20, 2),
  ('mission-be-kafka-07-o1-c1', 'solution', 'ev2: only 4 partitions exist, so a group of 5 consumers structurally cannot give the 5th one anything to own -- it sits idle by design, not by malfunction.', 30, 3),

  ('mission-be-kafka-08-o1-c1', 'orientation', 'A hash function applied to the same input always produces the same output. What happens when there''s no input to hash at all?', 10, 1),
  ('mission-be-kafka-08-o1-c1', 'solution', 'b: a key routes deterministically via a hash, guaranteeing the same key always lands in the same partition; no key means no such guarantee, typically a rotation across partitions instead.', 20, 2),
  ('mission-be-kafka-08-o2-c1', 'orientation', 'Compare this call to the one from the earlier objective -- something present there is missing here.', 10, 1),
  ('mission-be-kafka-08-o2-c1', 'concept', 'Without a key, Kafka has no reason to send every event for the same citizen to the same partition -- and only a single partition''s log is ordered.', 20, 2),
  ('mission-be-kafka-08-o2-c1', 'solution', 'The message object never sets a key, so events for the same citizen scatter across partitions instead of landing together in order -- it needs key: event.citizenId.', 30, 3),

  ('mission-be-kafka-09-o1-c1', 'orientation', 'The request and the failed attempt both describe symptoms of the same underlying setting. Find the setting itself.', 10, 1),
  ('mission-be-kafka-09-o1-c1', 'concept', 'retention.ms isn''t a soft suggestion -- once a segment ages past it, Kafka physically deletes it from disk. There''s nothing left to seek back to.', 20, 2),
  ('mission-be-kafka-09-o1-c1', 'solution', 'ev1: 7-day retention means anything older than 7 days has already been deleted from disk -- the auditors'' 45-day request is asking for data that no longer physically exists.', 30, 3),

  ('mission-be-kafka-10-o1-c1', 'orientation', 'A commit is a promise about the past, not a plan for the future. Check what''s promised before the work it''s promising even starts.', 10, 1),
  ('mission-be-kafka-10-o1-c1', 'concept', 'Committing before processing means a crash during processing leaves Kafka believing the event is fully handled, even though it never was.', 20, 2),
  ('mission-be-kafka-10-o1-c1', 'solution', 'consumer.commitOffsets(...) runs before processAdvisory -- it should run after processing succeeds, not before it''s even attempted.', 30, 3),
  ('mission-be-kafka-10-o2-c1', 'orientation', 'Nothing can be reassigned until it''s first taken away, and nothing gets taken away without a reason.', 10, 1),
  ('mission-be-kafka-10-o2-c1', 'concept', 'A rebalance is stop-the-world for the group by design -- every partition is revoked before any new assignment is computed, so there''s always a gap where nobody owns anything.', 20, 2),
  ('mission-be-kafka-10-o2-c1', 'solution', 'Membership changes, then every partition is revoked, then a new assignment is computed, then each consumer resumes from its last committed offset.', 30, 3),

  ('mission-be-kafka-11-o1-c1', 'orientation', 'Two of these are single delivery guarantees, each with a specific failure mode. One isn''t a delivery guarantee at all.', 10, 1),
  ('mission-be-kafka-11-o1-c1', 'solution', 'Commit-before-processing is at-most-once, commit-after-processing is at-least-once, idempotent producer plus repeat-safe processing is effectively-once.', 20, 2),

  ('mission-be-kafka-12-o1-c1', 'orientation', 'The rebalance completing cleanly and the deploy having no logic changes are both reassuring. Neither explains the duplicates.', 10, 1),
  ('mission-be-kafka-12-o1-c1', 'concept', 'A rebalance hands the new owner whatever was last committed -- if that committed offset is behind the true processed position, the gap between them gets processed again by someone else.', 20, 2),
  ('mission-be-kafka-12-o1-c1', 'solution', 'ev2: 15 events were processed but never committed before the rebalance took the partition away -- the new owner starts from the stale committed offset and reprocesses exactly those 15.', 30, 3),
  ('mission-be-kafka-12-o2-c1', 'orientation', 'The fix needs to survive the next rebalance too, not just patch this one incident.', 10, 1),
  ('mission-be-kafka-12-o2-c1', 'solution', 'c: committing only after processing completes shrinks the gap a rebalance can expose, and idempotent processing means any events that do get reprocessed don''t corrupt state.', 20, 2),
  ('mission-be-kafka-12-o3-c1', 'orientation', 'The other exchanges -- partitions, in this case -- behaving normally is reassuring. It isn''t new information about what the audit found.', 10, 1),
  ('mission-be-kafka-12-o3-c1', 'concept', 'A malformed key that no code path has ever rejected, sitting in the single most-reprocessed partition in the topic, is the one entry the audit wasn''t expecting to find.', 20, 2),
  ('mission-be-kafka-12-o3-c1', 'solution', 'ev2: the doubled-slash citizen key and partition 4''s disproportionate reprocessing history are the actual new finding -- not just confirmation the rebalance itself worked correctly.', 30, 3),
  ('mission-be-kafka-12-o4-c1', 'orientation', 'This incident had two separate jobs: fix the technical bug, and register what the audit turned up along the way.', 15, 1),
  ('mission-be-kafka-12-o4-c1', 'solution', 'Committing only after processing completes, with idempotent handling as a backstop, closes the redelivery gap for good. Separately, partition 4''s doubled-slash key and its reprocessing history are filed, unresolved, as the pattern reaching the event-streaming layer.', 25, 2);
